using System;
using System.Linq;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
namespace LittleNotebook {
 public sealed partial class MiniSurface {
  static readonly Color[] PuzzleColours={Color.FromRgb(116,165,133),Color.FromRgb(224,158,156),Color.FromRgb(124,171,203),Color.FromRgb(231,190,98),Color.FromRgb(174,149,193),Color.FromRgb(212,150,106),Color.FromRgb(95,181,181),Color.FromRgb(193,167,143),Color.FromRgb(153,184,103)};
  Rect ExtraCell(int index){var b=Session.Extra;double size=Math.Min(85,(b.Kind=="domino"?270.0:b.Kind=="flood"?310.0:350.0)/Math.Max(b.W,b.H));double x=(680-b.W*size)/2,y=b.Kind=="domino"||b.Kind=="flood"?12:(408-b.H*size)/2;return new Rect(x+index%b.W*size,y+index/b.W*size,size,size);}
  Point Mid(Rect r){return new Point(r.X+r.Width/2,r.Y+r.Height/2);}
  Rect TubeRect(int index){int n=Session.Extra.Tubes.Count;double step=Math.Min(77,620.0/n);return new Rect((680-n*step)/2+index*step+5,75,step-10,234);}
  void DrawExtra(DrawingContext dc){var b=Session.Extra;
   if(b.Kind=="untangle"){for(int e=0;e<b.Edges.Count;e++){bool cross=Enumerable.Range(0,b.Edges.Count).Any(i=>i!=e&&b.EdgesCross(e,i));var edge=b.Edges[e];dc.DrawLine(Pen(cross?Color.FromRgb(194,116,115):palette.Accent,3),b.Points[edge[0]],b.Points[edge[1]]);}for(int i=0;i<b.Points.Count;i++){dc.DrawEllipse(Brush(i==b.Selected?palette.Gold:palette.Light),Pen(palette.Ink,2),b.Points[i],13,13);Label(dc,(i+1).ToString(),b.Points[i],11);}return;}
   if(b.Kind=="pour"){for(int i=0;i<b.Tubes.Count;i++){var r=TubeRect(i);dc.DrawRoundedRectangle(Brush(Blend(palette.Line,.15)),Pen(i==b.Selected?palette.Gold:palette.Ink,i==b.Selected?3:1.5),r,9,9);for(int j=0;j<b.Tubes[i].Count;j++){int c=b.Tubes[i][j];if(b.Feedback>0&&b.Selected<0&&i==b.LastTo&&j==b.Tubes[i].Count-1)continue;var band=new Rect(r.X+4,r.Bottom-8-(j+1)*51,r.Width-8,48);dc.DrawRoundedRectangle(Brush(PuzzleColours[c]),null,band,5,5);Label(dc,((char)('A'+c)).ToString(),Mid(band),15,palette.Ink);}Label(dc,(i+1).ToString(),new Point(r.X+r.Width/2,r.Bottom+20),13);}if(b.Feedback>0&&b.Selected<0&&b.LastFrom>=0){Rect a=TubeRect(b.LastFrom),z=TubeRect(b.LastTo);Point from=new Point(a.X+a.Width/2,a.Bottom-8-(b.Tubes[b.LastFrom].Count+.5)*51),to=new Point(z.X+z.Width/2,z.Bottom-8-(b.Tubes[b.LastTo].Count-.5)*51);double t=1-Math.Max(0,b.Feedback)/.22;Point drop=from+(to-from)*t;drop.Y-=Math.Sin(t*Math.PI)*55;dc.DrawEllipse(Brush(PuzzleColours[b.LastColour]),Pen(palette.Ink,1),drop,17,17);Label(dc,((char)('A'+b.LastColour)).ToString(),drop,13);}
   Label(dc,ar?"انقل قطرة إلى لون مطابق أو أنبوب فارغ":"Move one drop onto its colour or into an empty tube",new Point(340,366),15);return;}
   if(b.Kind=="code"){int rows=b.Limit;double step=Math.Min(25,260.0/rows);for(int row=0;row<rows;row++)for(int col=0;col<b.W;col++)dc.DrawEllipse(null,Pen(palette.Line,1),new Point(100+col*47,20+row*step),9,9);for(int row=0;row<b.Guesses.Count;row++){for(int x=0;x<b.W;x++){Point at=new Point(100+x*47,20+row*step);dc.DrawEllipse(Brush(PuzzleColours[b.Guesses[row][x]]),Pen(palette.Ink,1),at,9,9);Label(dc,((char)('A'+b.Guesses[row][x])).ToString(),at,10);}Label(dc,b.Scores[row][0]+" ●   "+b.Scores[row][1]+" ○",new Point(480,20+row*step),14);}for(int x=0;x<b.W;x++){Point at=new Point(110+x*57,308);dc.DrawEllipse(b.Cells[x]<0?Brush(palette.Paper):Brush(PuzzleColours[b.Cells[x]]),Pen(x==b.Focus?palette.Gold:palette.Ink,x==b.Focus?3:1),at,20,20);Label(dc,b.Cells[x]<0?"?":((char)('A'+b.Cells[x])).ToString(),at,17);}for(int c=0;c<b.Colours;c++){Point at=new Point(65+c*45,368);dc.DrawEllipse(Brush(PuzzleColours[c]),Pen(palette.Ink,1),at,17,17);Label(dc,((char)('A'+c)).ToString(),at,14);}dc.DrawRoundedRectangle(Brush(palette.Light),Pen(palette.Ink,1.3),new Rect(475,342,168,48),8,8);Label(dc,ar?"اختبر الرمز":"Check code",new Point(559,365),17);return;}
   for(int i=0;i<b.Cells.Length;i++){Rect r=ExtraCell(i);Point center=Mid(r);r.Inflate(-2,-2);int v=b.Cells[i];Color fill=palette.Paper;
    if(b.Kind=="flood")fill=PuzzleColours[v];if(b.Kind=="lights")fill=v==1?palette.Gold:Blend(palette.Ink,.12);if(b.Kind=="queens")fill=(i%b.W+i/b.W)%2==0?palette.Light:palette.Paper;if((b.Kind=="crates"||b.Kind=="glide")&&v==-1)fill=Blend(palette.Ink,.40);
    dc.DrawRoundedRectangle(Brush(fill),Pen((i==b.Selected&&b.Kind!="glide"||IsKeyboardFocusWithin&&i==b.Focus&&b.Kind!="pour"&&b.Kind!="code")?palette.Gold:palette.Line,i==b.Selected?2:1),r,5,5);
    if(b.Kind=="lights"&&v==1){dc.DrawEllipse(Brush(palette.Paper),Pen(palette.Ink,1),center,Math.Min(11,r.Width*.22),Math.Min(11,r.Width*.22));}
    if(b.Kind=="queens"&&v==1){Color colour=b.Conflict(i)?Color.FromRgb(196,101,104):palette.Accent;dc.DrawGeometry(Brush(colour),Pen(palette.Ink,1.4),Geometry.Parse("M"+(center.X-12)+","+(center.Y+8)+" l-3,-19 10,7 5,-12 5,12 10,-7 -3,19 Z"));dc.DrawLine(Pen(palette.Ink,2),center+new Vector(-12,12),center+new Vector(12,12));if(b.Given[i]==1)dc.DrawEllipse(Brush(palette.Gold),null,center+new Vector(0,1),2,2);}
    if(b.Kind=="crates"){if(b.Goal[i]==1)DrawLeaf(dc,center,Math.Min(12,r.Width*.23),palette);if(v==1){Rect crate=r;crate.Inflate(-6,-6);dc.DrawRoundedRectangle(Brush(Color.FromRgb(209,172,128)),Pen(palette.Ink,1.5),crate,3,3);dc.DrawLine(Pen(palette.Ink,1),crate.TopLeft,crate.BottomRight);dc.DrawLine(Pen(palette.Ink,1),crate.TopRight,crate.BottomLeft);if(b.Goal[i]==1)dc.DrawEllipse(Brush(palette.Accent),null,center,5,5);}if(i==b.Player){if(b.PreviousPlayer>=0&&b.Feedback>0){Point previous=Mid(ExtraCell(b.PreviousPlayer));center=previous+(center-previous)*(1-Math.Min(1,b.Feedback/.18));}DrawLadybug(dc,center,Math.Min(12,r.Width*.25),0,palette);}}
    if(b.Kind=="pegs")dc.DrawEllipse(v==1?Brush(palette.Accent):null,Pen(i==b.Selected?palette.Gold:palette.Ink,i==b.Selected?3:1),center,r.Width*.27,r.Height*.27);
    if(b.Kind=="domino"){int value=v<0?-v-1:v;if(v<0)dc.DrawRoundedRectangle(Brush(Blend(palette.Accent,.18)),null,r,4,4);Label(dc,value.ToString(),center,Math.Min(24,r.Width*.48));}
    if(b.Kind=="glide"){if(i==b.Selected)DrawLeaf(dc,center,Math.Min(13,r.Width*.3),palette);if(i==b.Player){dc.DrawEllipse(Brush(PuzzleColours[2]),Pen(palette.Ink,1.5),center,r.Width*.28,r.Height*.28);dc.DrawEllipse(Brushes.White,null,center+new Vector(-3,-3),3,3);}}
    if(b.Kind=="flood")Label(dc,((char)('A'+v)).ToString(),center,Math.Min(13,r.Width*.44));
   }
   if(b.Kind=="domino"){for(int j=0;j<b.Solution.Count;j++){int a=b.Solution[j]/1000,z=b.Solution[j]%1000;int av=b.Cells[a]<0?-b.Cells[a]-1:b.Cells[a],zv=b.Cells[z]<0?-b.Cells[z]-1:b.Cells[z];bool used=b.Edges.Any(e=>e[0]==Math.Min(av,zv)*10+Math.Max(av,zv));Label(dc,(used?"✓ ":"")+av+"·"+zv,new Point(160+j%6*72,310+j/6*28),14,used?palette.Accent:palette.Ink);}}
   if(b.Kind=="domino")foreach(var edge in b.Edges){Rect a=ExtraCell(edge[2]),z=ExtraCell(edge[3]);a.Union(z);a.Inflate(-1,-1);dc.DrawRoundedRectangle(null,Pen(palette.Accent,3),a,6,6);}
   if(b.Kind=="flood"){for(int c=0;c<b.Colours;c++){Point center=new Point(200+c*54,392);dc.DrawEllipse(Brush(PuzzleColours[c]),Pen(palette.Ink,1),center,15,15);Label(dc,((char)('A'+c)).ToString(),center,13);}}
   if(b.Feedback>0&&b.Last>=0&&b.Last<b.Cells.Length){Rect flash=ExtraCell(b.Last);flash.Inflate(-1,-1);dc.DrawRoundedRectangle(null,Pen(b.Message=="blocked"?Color.FromRgb(195,113,105):palette.Gold,2.5),flash,5,5);}
  }
  int ExtraHit(Point point){var b=Session.Extra;if(b.Kind=="untangle")return Enumerable.Range(0,b.Points.Count).FirstOrDefault(i=>(b.Points[i]-point).Length<20,-1);if(b.Kind=="pour")return Enumerable.Range(0,b.Tubes.Count).FirstOrDefault(i=>TubeRect(i).Contains(point),-1);if(b.Kind=="code"){if(new Rect(475,342,168,48).Contains(point))return 99;for(int i=0;i<b.Colours;i++)if((point-new Point(65+i*45,368)).Length<21)return 100+i;for(int i=0;i<b.W;i++)if((point-new Point(110+i*57,308)).Length<24)return i;return -1;}if(b.Kind=="flood"){for(int i=0;i<b.Colours;i++)if((point-new Point(200+i*54,392)).Length<21)return i;int cell=Enumerable.Range(0,b.Cells.Length).FirstOrDefault(i=>ExtraCell(i).Contains(point),-1);return cell<0?-1:b.Cells[cell];}return Enumerable.Range(0,b.Cells.Length).FirstOrDefault(i=>ExtraCell(i).Contains(point),-1);}
 }
}
